/* ============================================================================
 * CONTENT · 06-media.js
 * 时代媒介时间轴 —— 「某个年代，话是靠什么传开的？」
 *
 * 这是给事件做「时代适配」用的。事件只要声明 medium，引擎就自动按年份放行：
 *     1840 年没人发推文；1960 年没有热搜；2008 年没有短视频。
 *
 * 字段：
 *     from  这个媒介从哪一年开始存在（必填）
 *     to    到哪一年为止（可选；不再用的话填上，比如电报）
 *     name  中文名
 *     note  一句话说明它给政治带来了什么变化（界面会给玩家看）
 *
 * 事件侧的写法（见 docs/CONTENT-SCHEMA.md）：
 *     medium: "tv"                  → 要有电视才可能发生
 *     medium: ["tv", "internet"]    → 电视或互联网，有其一就行（"靠哪种都传得开"）
 *     不写 medium                    → 任何年代都可能发生（报纸时代的常青事件）
 *     再配 fromYear / toYear / years:[a,b] 可以把窗口卡得更死。
 *
 * 想让某个大事件"到了这个媒介出现时才登场"：给它一个较晚的 medium + grade:"major"。
 * ==========================================================================*/

POTUS.define("medium", {
  print: {
    name: "报纸", from: 1700,
    note: "党报与黄页式的城市报纸主宰舆论，一封信就能毁掉一个人。"
  },
  radio: {
    name: "广播", from: 1920,
    note: "声音第一次直接进入客厅，一个人可以不靠集会直接对全国说话。"
  },
  tv: {
    name: "电视", from: 1948,
    note: "形象压过文字。会不会上镜、敢不敢直播，开始决定选举。"
  },
  cable: {
    name: "有线电视", from: 1980,
    note: "二十四小时新闻频道与立场鲜明的谈话节目，把舆论拆成了两个世界。"
  },
  internet: {
    name: "互联网", from: 1995,
    note: "线索、档案、匿名者。信息不再经过编辑部，但也无人把关。"
  },
  social: {
    name: "社交媒体", from: 2008,
    note: "每个人都成了发布者。一条 140 字的情绪，可能比一场演讲传得更远。"
  },
  shortvideo: {
    name: "短视频", from: 2018,
    note: "十五秒定生死。算法的分发权，成了新的党鞭。"
  },
  deepfake: {
    name: "合成影像", from: 2022,
    note: "「眼见为实」失效了。你连否认都要先证明那段视频不是你。"
  }
});
